/**
 * Which layer a check belongs to.
 */
export type CalculationSummaryVerificationLayer = "document" | "store";

/**
 * The verdict on one summary.
 *
 * Attributes: VERIFIED: Every check passed and the signing key is pinned -- to
 * an explicitly trusted key, or to this profile's key by the store layer.
 * VERIFIED_WITH_LATER_CHANGES: Verified against the store, which records a
 * later lifecycle step the export predates. VALID_UNPINNED: Every document
 * check passed but no key was trusted and the store was not consulted, so a
 * consistent forgery is not excluded. REFUSED: At least one check failed, or
 * the store layer cannot prove the file.
 */
export type CalculationSummaryVerificationOutcome =
  "verified" | "verified_with_later_changes" | "valid_unpinned" | "refused";

